it('uses the current project for the owned WSL shell default after its workspace is removed', async () => {
 const root=await mkdtemp(join(process.env.IH_NATIVE_DEPENDENCY_EVIDENCE_ROOT!,'owned-wsl-project-'))
 const source=join(root,'source'),workspace=join(source,'nested'),destination=join(root,'destination'),explicitDirectory=join(root,'other-member')
 await Promise.all([mkdir(workspace,{recursive:true}),mkdir(destination),mkdir(explicitDirectory)])
 const coordinator=composeJsonlTaskTransitionCoordinator(createJsonlBackend(join(root,'sessions')),{lock:{enabled:true},originalExecutionFoldFactory:createOwnedMetadataFold},taskDocumentStorageContract)
 await coordinator.create({sessionId:'main'})
 const output=createContextOutputService({root:join(root,'results'),workspaceId:'fixture',config:{enabled:false}})
 const environment=createProjectInstructionEnvironment()
 let authority:AuthorityState={kind:'bound',revision:'source',primaryRoot:source,roots:[source],references:[]}
 const prepared:ProcessSpec[]=[]
 const native:TransportExecutionBackend={
  async probe(){return {id:'fixture',availability:'available',assurance:'experimental',features:{writeIsolation:true,readIsolation:false,denyPaths:false,pipes:true,pty:false,retainedTree:false}}},
  async prepare(spec,policy){
   if(spec.executionTarget==='wsl'&&process.platform==='win32')captureRequest(spec,policy)
   prepared.push(spec)
   return {policy,async rollback(){},async commit(check){
    check()
    const lease=createExecutionLease({receipt:{executionId:'native-'+prepared.length,backendId:'fixture',policyFingerprint:policy.fingerprint,owner:spec.owner,assurance:'experimental'},rootExited:Promise.resolve({exitCode:0}),async waitTreeEmpty(){},async settleIo(){},async releaseResources(){},async terminate(){}})
    return {...lease,get settled(){return lease.settled},pid:1,io:{async write(){},async endInput(){},output:(async function*(){yield {channel:'stdout' as const,data:Buffer.from(spec.cwd)}})()}}
   }}
  },
 }
 const wire=(id?:string)=>`data: ${JSON.stringify({choices:[{delta:id?{tool_calls:[{index:0,id,function:{name:'shell',arguments:JSON.stringify({command:'pwd'})}}]}:{content:'done'},finish_reason:id?'tool_calls':'stop'}],usage:{prompt_tokens:20,completion_tokens:2}})}\n\ndata: [DONE]\n\n`
 const server=await createLoopbackProvider('/v1/chat/completions',['inside',undefined,'moved',undefined].map(id=>async response=>{response.end(wire(id))}))
 let shell:ExecService|undefined
 const service=createSessionService({workspace,coordinator,contextWindow:4096,maxOutputTokens:128,
  model:createOpenAICompatibleClient({apiKey:'loopback',model:'fixture',baseUrl:server.baseUrl}),
  managedRuntime:{systemPrompt:'system',tools:[],async acquireInstructions(){return {environment,cwd:workspace,authority:()=>authority,available:()=>true}},
   async mountDefaultSurface(_original,live){shell=live.shell;return {systemPrompt:()=> 'system',modelToolSchemas:live.modelToolSchemas,modelOverheadTokens:()=>0,prepareInput:async input=>input,async reconcileAuthority(){}}},
   ownedShell:{executionFor(sessionId){return {defaultOwner:{sessionId},selectBackend:()=>native,resolvePolicy:owner=>compileExecutionPolicy({mode:'workspace-write',owner,authority}),validateAuthority(){}}},
    async acquireOutput(_id,retain){retain(()=>output.close());return {service:output}},
    agentShell:()=>({id:'wsl-fixture',label:'Fixture Bash',command:'/bin/bash',dialect:'posix',executionTarget:'wsl'}),
   },
  },
 })
 try {
  await service.submit('main','run inside the source project',new AbortController().signal)
  expect(prepared).toMatchObject([{executionTarget:'wsl',cwd:workspace}])

  authority={kind:'bound',revision:'destination',primaryRoot:destination,roots:[destination,explicitDirectory],references:[]}
  await service.submit('main','run in the destination project',new AbortController().signal)
  expect(prepared).toMatchObject([{cwd:workspace},{executionTarget:'wsl',cwd:destination}])
  expect(server.requests).toHaveLength(4)

  const command={argv:['/bin/bash','-c','pwd'],executionTarget:'wsl' as const}
  await shell!.run({...command,cwd:explicitDirectory})
  expect(prepared.at(-1)?.cwd).toBe(explicitDirectory)
  if(process.platform==='win32')await expect(shell!.run({...command,cwd:workspace})).rejects.toThrow(/cwd\/primary root is outside authority/)
  await shell!.run({argv:[process.execPath,'--version'],executionTarget:'host'})
  expect(prepared.at(-1)).toMatchObject({executionTarget:'host',cwd:workspace})

  authority={kind:'bound',revision:'invalid-primary',primaryRoot:workspace,roots:[destination],references:[workspace]}
  await expect(async()=>shell!.run(command)).rejects.toThrow(/project working directory unavailable/)
  authority={kind:'revoked',revision:'withdrawn',reason:'Project removed'}
  await expect(async()=>shell!.run(command)).rejects.toThrow(/revoked/)
  expect(prepared).toHaveLength(4)
 } finally {
  await service.close();await environment.close();await coordinator.close();await server.close()
 }
},60000)

it.each(['session','service'] as const)('retires private delivery at clean %s close and settles the original native Shell',async closeScope=>{
 const root=await mkdtemp(join(process.env.IH_NATIVE_DEPENDENCY_EVIDENCE_ROOT!,'owned-service-shell-'))
 const coordinator=composeJsonlTaskTransitionCoordinator(createJsonlBackend(join(root,'sessions')),{lock:{enabled:true},originalExecutionFoldFactory:createOwnedMetadataFold},taskDocumentStorageContract);await coordinator.create({sessionId:'main'})
 const output=createContextOutputService({root:join(root,'results'),workspaceId:'fixture',config:{enabled:false}});let launches=0,releases=0
 const done=Promise.withResolvers<void>()
 const native:TransportExecutionBackend={async probe(){return{id:'controlled',availability:'available',assurance:'unverified',features:{writeIsolation:false,readIsolation:false,denyPaths:false,pipes:true,pty:false,retainedTree:true}}},async prepare(spec,policy){return {policy,async rollback(){},async commit(check){check();launches++;const lease=createExecutionLease({receipt:{executionId:'native-actual',backendId:'controlled',policyFingerprint:policy.fingerprint,owner:spec.owner,assurance:'unverified'},rootExited:done.promise.then(()=>({exitCode:0})),waitTreeEmpty:()=>done.promise,settleIo:async()=>{},async releaseResources(){releases++},async terminate(){done.resolve()}});done.resolve();return {...lease,get settled(){return lease.settled},pid:1,io:{async write(){},async endInput(){},output:(async function*(){yield {channel:'stdout' as const,data:Buffer.from('actual native output')}})()}}}}}}
 const execution={defaultOwner:{sessionId:'main'},selectBackend:()=>native,resolvePolicy:(owner:Parameters<typeof compileExecutionPolicy>[0]['owner'])=>compileExecutionPolicy({mode:'danger-full-access',owner,authority:{kind:'unbound',revision:'fixture',workspaceRoot:root}}),validateAuthority(){}}
 const wire=(tool:boolean)=>`data: ${JSON.stringify({choices:[{delta:tool?{tool_calls:[{index:0,id:'shell-1',function:{name:'shell',arguments:JSON.stringify({command:'controlled'})}}]}:{content:'done'},finish_reason:tool?'tool_calls':'stop'}],usage:{prompt_tokens:20,completion_tokens:2}})}\n\ndata: [DONE]\n\n`
 const server=await createLoopbackProvider('/v1/chat/completions',[async r=>{r.end(wire(true))},async r=>{r.end(wire(false))}])
 const service=createSessionService({workspace:root,coordinator,managedRuntime:{systemPrompt:'system',tools:[],ownedShell:{executionFor(id){return {...execution,defaultOwner:{sessionId:id}}},async acquireOutput(_id,retain){retain(()=>output.close());return {service:output}},agentShell:()=>({id:'controlled',label:'controlled',command:'controlled',dialect:'posix'})}},model:createOpenAICompatibleClient({apiKey:'loopback',model:'fixture',baseUrl:server.baseUrl}),contextWindow:4096,maxOutputTokens:128})
 const warn=vi.spyOn(console,'warn')
 try{
  await service.submit('main','run controlled',new AbortController().signal)
  expect(JSON.stringify(server.requests[0]!.body)).toContain('"name":"shell"')
  expect(launches).toBe(1)
  expect(server.requests).toHaveLength(2)
  const runtime=originalManagedRuntimeFor(service,'main')!
  const stopped=Promise.withResolvers<{error:unknown;terminal:boolean}>()
  const off=subscribeManagedExecutionReadiness(runtime.domain,()=>{},(error,terminal)=>stopped.resolve({error,terminal}))
  try{
   if(closeScope==='session')await service.closeSession('main')
   else await service.close()
   expect(await stopped.promise).toMatchObject({error:{code:'FACT_CLOSED'},terminal:true})
  }finally{off()}
  expect(warn.mock.calls.map(args=>args.map(String).join(' ')).filter(message=>message.includes('private delivery readiness unavailable'))).toEqual([])
  expect(releases).toBe(1)
 }finally{warn.mockRestore();done.resolve();await service.close();await coordinator.close();await server.close()}
},60000)

it('wakes the original private service after a background Shell receipt',async()=>{
 const root=await mkdtemp(join(process.env.IH_NATIVE_DEPENDENCY_EVIDENCE_ROOT!,'owned-shell-wake-'))
 const backend=createJsonlBackend(join(root,'sessions')),coordinator=composeJsonlTaskTransitionCoordinator(backend,{lock:{enabled:true},originalExecutionFoldFactory:createOwnedMetadataFold},taskDocumentStorageContract);await coordinator.create({sessionId:'main'})
 const output=createContextOutputService({root:join(root,'results'),workspaceId:'fixture',config:{enabled:false}});let launches=0,releases=0
 const done=Promise.withResolvers<void>()
 const native:TransportExecutionBackend={async probe(){return{id:'controlled',availability:'available',assurance:'unverified',features:{writeIsolation:false,readIsolation:false,denyPaths:false,pipes:true,pty:false,retainedTree:true}}},async prepare(spec,policy){return {policy,async rollback(){},async commit(check){check();launches++;const lease=createExecutionLease({receipt:{executionId:'native-actual',backendId:'controlled',policyFingerprint:policy.fingerprint,owner:spec.owner,assurance:'unverified'},rootExited:done.promise.then(()=>({exitCode:0})),waitTreeEmpty:()=>done.promise,settleIo:async()=>{},async releaseResources(){releases++},async terminate(){done.resolve()}});return {...lease,get settled(){return lease.settled},pid:1,io:{async write(){},async endInput(){},output:(async function*(){yield {channel:'stdout' as const,data:Buffer.from('actual native output')};await done.promise})()}}}}}}
 const execution={defaultOwner:{sessionId:'main'},selectBackend:()=>native,resolvePolicy:(owner:Parameters<typeof compileExecutionPolicy>[0]['owner'])=>compileExecutionPolicy({mode:'danger-full-access',owner,authority:{kind:'unbound',revision:'fixture',workspaceRoot:root}}),validateAuthority(){}}
 const wire=(tool:boolean)=>`data: ${JSON.stringify({choices:[{delta:tool?{tool_calls:[{index:0,id:'shell-1',function:{name:'shell',arguments:JSON.stringify({command:'controlled',background:true})}}]}:{content:'done'},finish_reason:tool?'tool_calls':'stop'}],usage:{prompt_tokens:20,completion_tokens:2}})}\n\ndata: [DONE]\n\n`
 const woken=Promise.withResolvers<void>()
 const server=await createLoopbackProvider('/v1/chat/completions',[async r=>{r.end(wire(true))},async r=>{r.end(wire(false))},async (r,request)=>{const messages=request.body.messages as {content?:string}[],content=messages.find(m=>typeof m.content==='string'&&m.content.startsWith('<exec_result>'))?.content;if(!content)throw Error('Original receipt missing');const data=JSON.parse(content.split('\n')[1]!);const call={choices:[{delta:{tool_calls:[{index:0,id:'read-1',function:{name:'context_output_read',arguments:JSON.stringify({ref:data.frames.retention.ref,maxBytes:1000})}}]},finish_reason:'tool_calls'}]};r.end(`data: ${JSON.stringify(call)}\n\ndata: [DONE]\n\n`)},async r=>{woken.resolve();r.end(wire(false))}])
 const service=createSessionService({workspace:root,coordinator,managedRuntime:{systemPrompt:'system',tools:[],ownedShell:{executionFor(id){return {...execution,defaultOwner:{sessionId:id}}},async acquireOutput(_id,retain){retain(()=>output.close());return {service:output}},agentShell:()=>({id:'controlled',label:'controlled',command:'controlled',dialect:'posix'})}},model:createOpenAICompatibleClient({apiKey:'loopback',model:'fixture',baseUrl:server.baseUrl}),contextWindow:4096,maxOutputTokens:128})
 try{await service.submit('main','run controlled',new AbortController().signal);expect(launches).toBe(1);expect(server.requests).toHaveLength(2);done.resolve();await Promise.race([woken.promise,new Promise((_,reject)=>setTimeout(()=>reject(Error('original receipt did not wake service')),35000))]);expect(server.requests).toHaveLength(4);expect(JSON.stringify(server.requests[2]!.body)).toContain('exec_result');expect(JSON.stringify(server.requests[3]!.body)).toContain(Buffer.from('actual native output').toString('base64'))}finally{done.resolve();await service.close();await coordinator.close();await server.close()}
 expect(releases).toBe(1)
},90000)

